  ('PF297712', '잔혹동화 생존기 [대학로]', 'musical', '2026-09-27', null, '18:00', '1층 A열 15', 8, ARRAY['김초하','선유하','선한국','신준석','최반석','한보라']::text[]),
  ('PF294425', '사칠', 'musical', '2026-09-30', null, '20:00', '1층 C열 1', 17, ARRAY['김재한','선한국']::text[]),
  ('PF297712', '잔혹동화 생존기 [대학로]', 'musical', '2026-10-01', null, '20:00', '1층 A열 6', 9, ARRAY['김이담','김초하','주다온','최반석','한보라']::text[]),
  ('PF294425', '사칠', 'musical', '2026-09-02', 3.5, '20:00', '1층 G열 1', 12, ARRAY['선한국','임태현']::text[])
) as v(kopis_id, title, sub_category, view_start, rating, show_time, seat, show_number, cast_names)
join performances p on coalesce(p.kopis_id, p.title) = coalesce(v.kopis_id, v.title)
where not exists (
  select 1 from records r
  where r.user_id = '3e4756d0-1ee5-4880-aa4f-206547c74d6b'::uuid
    and r.category = 'performance'
    and r.view_start = v.view_start::date
    and r.show_time is not distinct from v.show_time
);

-- 3) 아직 안 본 관람은 '관람 예정'으로
--    2번에서 일단 'done' 으로 넣고 여기서 뒤집는다. status 가 enum 이라
--    VALUES 를 거치면 text 로 굳어버리는데, update 의 리터럴은 그냥 enum 으로 해석되기 때문.
--    실행 시점 기준이라 나중에 다시 돌려도 알아서 맞는다.
update records set status = 'planned'
where user_id = '3e4756d0-1ee5-4880-aa4f-206547c74d6b'::uuid
  and category = 'performance'
  and status = 'done'
  and view_start + coalesce(show_time, '00:00')::time > (now() at time zone 'Asia/Seoul');

commit;
